local _, TRB = ...

-- Rogue options (The Burning Crusade Classic): default settings, default bar text and the options
-- panel, generated by the options template from the class archetypes.

---Which threshold lines start enabled: the rotational abilities, with situational utility left off.
---@return table
local function LoadDefaultThresholdDictionary()
	return {
		sinisterStrike = { enabled = true },
		backstab = { enabled = true },
		hemorrhage = { enabled = true },
		ghostlyStrike = { enabled = true },
		mutilate = { enabled = true },
		shiv = { enabled = false },
		ambush = { enabled = true },
		garrote = { enabled = true },
		cheapShot = { enabled = true },
		gouge = { enabled = true },
		riposte = { enabled = false },
		eviscerate = { enabled = true },
		envenom = { enabled = true },
		rupture = { enabled = true },
		sliceAndDice = { enabled = true },
		kidneyShot = { enabled = true },
		exposeArmor = { enabled = true },
		deadlyThrow = { enabled = false },
		feint = { enabled = false },
		sap = { enabled = false },
		kick = { enabled = true },
		distract = { enabled = false },
		blind = { enabled = false },
		shadowstep = { enabled = false },
		bladeFlurry = { enabled = true },
	}
end

TRB.TBC.Templates.Options:Install("rogue", {
	general = LoadDefaultThresholdDictionary,
})
